    shape: TLTextShape,
  ): ReturnType<TextShapeUtil["component"]> {
    const url = getTextShapeUrl(shape);
    return (
      <>
        {super.component(shape)}
        {url && (
          <HyperlinkButton url={url} zoomLevel={this.editor.getZoomLevel()} />
        )}
      </>
    ) as ReturnType<TextShapeUtil["component"]>;
  }
}

