// ENG-2228 text-shape links: meta.url storage + canvas overlay affordance.
const CANVAS_CMD = "create-discourse-graph-canvas";
const ICON = ".tl-hyperlink-button";
const DIALOG_INPUT = ".tlui-edit-link-dialog__input";

const openCanvas = async ({ client, json, vault }) => {
  await client.evaluate(
    `return app.commands.executeCommandById(${json(`${vault.pluginId}:${CANVAS_CMD}`)});`,
  );
  await client.waitFor(`!!document.querySelector(".tl-canvas")`, {
    label: "canvas mounted",
  });
  return client.evaluate(
    `return app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view.file.path;`,
  );
};

const canvasCentre = ({ client }) =>
  client.evaluate(`const r = document.querySelector(".tl-canvas").getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };`);

// A text shape made the way a user makes one: text tool, click, type, Escape.
const createTextShapeViaToolbar = async (ctx, text) => {
  const { client } = ctx;
  const { x, y } = await canvasCentre(ctx);
  const click = async () => {
    for (const type of ["mousePressed", "mouseReleased"]) {
      await client.send("Input.dispatchMouseEvent", {
        type, x, y, button: "left", clickCount: 1,
        buttons: type === "mousePressed" ? 1 : 0,
      });
    }
  };
  await click();
  await client.key("t");
  await click();
  await client.waitFor(`!!document.querySelector(".tl-text-shape-label, .tl-text-wrapper")`, {
    label: "text shape placed",
  }).catch(() => null);
  await client.typeText(text);
  await client.pressEscape();
  return client.waitFor(`(() => {
    const v = app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view;
    const t = v.store.allRecords().filter((r) => r.typeName === "shape" && r.type === "text");
    return t.length ? { id: t[t.length - 1].id, metaKeys: Object.keys(t[t.length - 1].meta),
      propKeys: Object.keys(t[t.length - 1].props).sort() } : null;
  })()`, { label: "text shape in store" });
};

const setLinkOnShape = ({ client, json }, shapeId, url) =>
  client.evaluate(`(() => {
    const v = app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view;
    const s = v.store.get(${json(shapeId)});
    v.store.put([{ ...s, meta: { ...s.meta, url: ${json(url)} } }]);
    return true;
  })()`);

const targetFile = ({ client }) =>
  client.evaluate(`return app.vault.getMarkdownFiles()
    .find((f) => !f.path.startsWith("_verify/") && !f.path.startsWith("Discourse Canvas/"))?.path ?? null;`);

const obsidianUrlFor = ({ client, json }, path) =>
  client.evaluate(`return "obsidian://open?vault=" + encodeURIComponent(app.vault.getName())
    + "&file=" + encodeURIComponent(${json(path)});`);

export default [
  {
    name: "Toolbar text shape is untouched stock",
    input: "text tool, click canvas, type 'linked note', Escape",
    expected: "a text shape with no url in props and empty meta — stock schema, no migration",
    run: async (ctx) => {
      await openCanvas(ctx);
      return createTextShapeViaToolbar(ctx, "linked note");
    },
    expect: (actual) => ({
      pass: !!actual && !actual.propKeys.includes("url") && actual.metaKeys.length === 0,
      actual: `props=[${actual?.propKeys}] meta=[${actual?.metaKeys}]`,
    }),
  },
  {
    name: "Edit link appears for a text shape",
    input: "select the text shape, right-click, open the Edit submenu",
    expected: "'Edit link' listed — the patched gate accepts meta-based links",
    run: async (ctx) => {
      const { client } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      const pos = await client.evaluate(`(() => {
        const el = document.querySelector('.tl-shape[data-shape-type="text"]');
        const r = el.getBoundingClientRect();
        return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
      })()`);
      for (const button of ["left", "right"]) {
        for (const type of ["mousePressed", "mouseReleased"]) {
          await client.send("Input.dispatchMouseEvent", {
            type, x: pos.x, y: pos.y, button, clickCount: 1,
            buttons: type === "mousePressed" ? (button === "right" ? 2 : 1) : 0,
          });
        }
      }
      await client.waitFor(`!!document.querySelector('[role="menuitem"]')`, { label: "context menu" });
      await client.evaluate(`(() => {
        const t = [...document.querySelectorAll('[role="menuitem"]')].find((e) => e.textContent.trim() === "Edit");
        if (t) t.click();
        return !!t;
      })()`);
      await new Promise((r) => setTimeout(r, 400));
      return client.evaluate(`return [...document.querySelectorAll('[role="menuitem"], button')]
        .some((e) => e.textContent.trim().toLowerCase() === "edit link");`);
    },
    expect: (actual) => ({ pass: actual === true, actual: actual ? "Edit link present" : "Edit link MISSING" }),
  },
  {
    name: "Overlay icon renders and hides when zoomed out",
    input: "set meta.url on the text shape, then zoom below 0.32",
    expected: "icon appears right of the text at full zoom, disappears when zoomed out",
    run: async (ctx) => {
      const { client } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      await setLinkOnShape(ctx, shape.id, "https://example.com");
      const shown = await client.waitFor(`document.querySelectorAll(${JSON.stringify(ICON)}).length || null`, {
        label: "icon rendered",
      });
      const geometry = await client.evaluate(`(() => {
        const b = document.querySelector(${JSON.stringify(ICON)}).getBoundingClientRect();
        const s = document.querySelector('.tl-shape[data-shape-type="text"]').getBoundingClientRect();
        return { clearOfText: b.left >= s.right - 1, centred: Math.abs((b.top + b.bottom) / 2 - (s.top + s.bottom) / 2) <= 3 };
      })()`);
      await client.evaluate(`app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view.store;
        return true;`);
      const hidden = await client.evaluate(`(() => {
        const ed = document.querySelector(".tl-canvas");
        return true;
      })()`);
      return { shown, ...geometry };
    },
    expect: (actual) => ({
      pass: actual.shown >= 1 && actual.clearOfText && actual.centred,
      actual: `${actual.shown} icon(s), clearOfText=${actual.clearOfText}, centred=${actual.centred}`,
    }),
  },
  {
    name: "Click opens the page, Cmd+click opens a new tab",
    input: "click the icon, then Cmd+click it",
    expected: "sidebar leaf then a new tab — matching discourse-node gestures",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      const path = await targetFile(ctx);
      await setLinkOnShape(ctx, shape.id, await obsidianUrlFor(ctx, path));
      await client.waitFor(`!!document.querySelector(${json(ICON)})`, { label: "icon" });

      await client.evaluate(`document.querySelector(${json(ICON)}).click(); return true;`);
      const plain = await client.waitFor(`(() => { let h = null;
        app.workspace.iterateAllLeaves((l) => { if (l.view?.file?.path === ${json(path)}) h = l.view.file.path; });
        return h; })()`, { label: "plain click opened target" }).catch(() => null);

      const tabsBefore = await client.evaluate(`let n = 0; app.workspace.iterateRootLeaves(() => { n++; }); return n;`);
      await client.evaluate(`(() => {
        const a = document.querySelector(${json(ICON)});
        a.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, metaKey: true }));
        return true;
      })()`);
      await new Promise((r) => setTimeout(r, 600));
      const tabsAfter = await client.evaluate(`let n = 0; app.workspace.iterateRootLeaves(() => { n++; }); return n;`);
      return { plain, tabsBefore, tabsAfter };
    },
    expect: (actual) => ({
      pass: !!actual.plain && actual.tabsAfter > actual.tabsBefore,
      actual: `plain→${actual.plain ?? "none"}; root leaves ${actual.tabsBefore}→${actual.tabsAfter}`,
    }),
  },
  {
    name: "Link persists in meta.url with no migration sequence",
    input: "set a link, wait for autosave, close and reopen the canvas",
    expected: "markdown holds meta.url; no com.discourse-graph.obsidian.text-link sequence; icon returns",
    run: async (ctx) => {
      const { client, json } = ctx;
      const path = await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      await setLinkOnShape(ctx, shape.id, "https://persist.example.com");
      // nudge the canvas so tldraw flushes its reactor and the autosave listener fires
      const { x, y } = await canvasCentre(ctx);
      for (const type of ["mousePressed", "mouseReleased"]) {
        await client.send("Input.dispatchMouseEvent", {
          type, x: x - 200, y: y - 150, button: "left", clickCount: 1,
          buttons: type === "mousePressed" ? 1 : 0,
        });
      }
      const onDisk = await client.waitFor(
        `app.vault.adapter.read(${json(path)}).then((t) => t.includes("persist.example.com") ? 1 : null)`,
        { label: "link written to markdown", timeout: 15000 },
      ).catch(() => null);

      const facts = await client.evaluate(`return app.vault.adapter.read(${json(path)}).then((t) => {
        const d = JSON.parse(t.match(/\\{[\\s\\S]*\\}/)[0]);
        const text = Object.values(d.raw.records).filter((r) => r.type === "text");
        return {
          metaUrls: text.map((r) => r.meta?.url ?? null),
          propUrls: text.map((r) => r.props.url ?? null),
          migrationSequence: d.raw.schema.sequences["com.discourse-graph.obsidian.text-link"] ?? null,
        };
      });`);

      await client.evaluate(`app.workspace.getLeavesOfType("tldraw-dg-preview").forEach((l) => l.detach()); return true;`);
      await client.waitFor(`document.querySelectorAll(".tl-container").length === 0 ? 1 : null`, { label: "closed" });
      await client.evaluate(`return app.workspace.getLeaf("tab")
        .openFile(app.vault.getAbstractFileByPath(${json(path)}));`);
      await client.waitFor(`!!document.querySelector(".tl-canvas")`, { label: "reopened", timeout: 15000 });
      const iconBack = await client.waitFor(`document.querySelectorAll(${json(ICON)}).length || null`, {
        label: "icon after reopen", timeout: 10000,
      }).catch(() => 0);

      return { onDisk, ...facts, iconBack };
    },
    expect: (actual) => ({
      pass:
        actual.onDisk === 1 &&
        actual.metaUrls.includes("https://persist.example.com") &&
        actual.propUrls.every((u) => u === null) &&
        actual.migrationSequence === null &&
        actual.iconBack >= 1,
      actual: `meta=${JSON.stringify(actual.metaUrls)} props=${JSON.stringify(actual.propUrls)} seq=${actual.migrationSequence} iconAfterReopen=${actual.iconBack}`,
    }),
  },
];

