const VIEW = `app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view`;
export default {
  name: "Geo shape accepts and opens an obsidian page link",
  input: "put obsidian://open on a geo shape, click its stock icon",
  expected: "schema accepts it; click opens the page in the sidebar, not the OS",
  run: async ({ client, json, vault }) => {
    await client.evaluate(
      `return app.commands.executeCommandById(${json(`${vault.pluginId}:create-discourse-graph-canvas`)});`,
    );
    await client.waitFor(`return !!document.querySelector(".tl-canvas");`, { timeout: 15000 });
    const path = await client.evaluate(`return app.vault.getMarkdownFiles()
      .find((f) => !f.path.startsWith("_verify/") && !f.path.startsWith("Discourse Canvas/"))?.path ?? null;`);
    const accepted = await client.evaluate(`const v = ${VIEW};
      const page = v.store.allRecords().find((r) => r.typeName === "page");
      const url = "obsidian://open?vault=" + encodeURIComponent(app.vault.getName())
        + "&file=" + encodeURIComponent(${json(path)});
      try {
        v.store.put([{ id: "shape:geoparity", typeName: "shape", type: "geo",
          x: 150, y: 150, rotation: 0, index: "a1", parentId: page.id,
          isLocked: false, opacity: 1, meta: {},
          props: { w: 220, h: 120, geo: "rectangle", color: "black", labelColor: "black",
            fill: "none", dash: "draw", size: "m", font: "draw", align: "middle",
            verticalAlign: "middle", growY: 0, scale: 1,
            richText: { type: "doc", content: [{ type: "paragraph", content: [{ type: "text", text: "geo" }] }] },
            url } }]);
        return "accepted";
      } catch (e) { return "REJECTED: " + (e.message || e); }`);
    if (accepted !== "accepted") return { accepted, opened: null };

    await client.waitFor(`return document.querySelectorAll(".tl-shape[data-shape-type='geo'] .tl-hyperlink-button").length > 0;`,
      { label: "geo icon", timeout: 8000 });
    const hrefOmitted = await client.evaluate(
      `return !document.querySelector(".tl-shape[data-shape-type='geo'] .tl-hyperlink-button").hasAttribute("href");`);
    await client.evaluate(
      `document.querySelector(".tl-shape[data-shape-type='geo'] .tl-hyperlink-button").click(); return true;`);
    const opened = await client.waitFor(`let hit = false;
      app.workspace.iterateAllLeaves((l) => { if (l.view && l.view.file && l.view.file.path === ${json(path)}) hit = true; });
      return hit;`, { label: "geo link opened the page", timeout: 8000 }).then(() => true).catch(() => false);
    return { accepted, hrefOmitted, opened };
  },
  expect: (a) => ({
    pass: a.accepted === "accepted" && a.hrefOmitted === true && a.opened === true,
    actual: `schema=${a.accepted}, href omitted=${a.hrefOmitted}, opened in app=${a.opened}`,
  }),
};
