1	import type { TLShape } from "tldraw";
2	
3	// An allowlist, not a parse check: the link renders as <a href>, so admitting
4	// arbitrary protocols would make `javascript:` an XSS vector.
5	const ALLOWED_WEB_PROTOCOLS = new Set(["http:", "https:", "mailto:"]);
6	
7	// Only obsidian://open?...file=... -- a bare `obsidian:` check would admit
8	// action URIs like advanced-uri's commandid from a shared canvas.
9	const isAllowedObsidianUrl = (url: URL): boolean =>
10	  // obsidian: is a non-special scheme, so WHATWG leaves the host case alone.
11	  url.host.toLowerCase() === "open" && !!url.searchParams.get("file");
12	
13	export const isAllowedTextLinkUrl = (value: string): boolean => {
14	  if (value === "") return true;
15	  try {
16	    const url = new URL(value);
17	    const protocol = url.protocol.toLowerCase();
18	    if (protocol === "obsidian:") return isAllowedObsidianUrl(url);
19	    return ALLOWED_WEB_PROTOCOLS.has(protocol);
20	  } catch {
21	    return false;
22	  }
23	};
24	
25	export const isObsidianUrl = (url: string): boolean => {
26	  try {
27	    return new URL(url).protocol.toLowerCase() === "obsidian:";
28	  } catch {
29	    return false;
30	  }
31	};
32	
33	// Returns the parsed form: `new URL` strips leading control characters, so a
34	// raw value could pass this allowlist and fail a prefix test further on.
35	export const getTextShapeLinkUrl = (shape: TLShape): string => {
36	  const raw = (shape.meta as { url?: unknown }).url;
37	  if (typeof raw !== "string" || !isAllowedTextLinkUrl(raw)) return "";
38	  try {
39	    return new URL(raw).toString();
40	  } catch {
41	    return "";
42	  }

