import type { TLShape } from "tldraw";

// An allowlist, not a parse check: the link renders as <a href>, so admitting
// arbitrary protocols would make `javascript:` an XSS vector.
const ALLOWED_WEB_PROTOCOLS = new Set(["http:", "https:", "mailto:"]);

// Only obsidian://open?...file=... -- a bare `obsidian:` check would admit
// action URIs like advanced-uri's commandid from a shared canvas.
const isAllowedObsidianUrl = (url: URL): boolean =>
  // obsidian: is a non-special scheme, so WHATWG leaves the host case alone.
  url.host.toLowerCase() === "open" && !!url.searchParams.get("file");

export const isAllowedTextLinkUrl = (value: string): boolean => {
  if (value === "") return true;
  try {
    const url = new URL(value);
    const protocol = url.protocol.toLowerCase();
    if (protocol === "obsidian:") return isAllowedObsidianUrl(url);
    return ALLOWED_WEB_PROTOCOLS.has(protocol);
  } catch {
    return false;
  }
};

export const isObsidianUrl = (url: string): boolean => {
  try {
    return new URL(url).protocol.toLowerCase() === "obsidian:";
  } catch {
    return false;
  }
};

// Returns the parsed form: `new URL` strips leading control characters, so a
// raw value could pass this allowlist and fail a prefix test further on.
export const getTextShapeLinkUrl = (shape: TLShape): string => {
  const raw = (shape.meta as { url?: unknown }).url;
  if (typeof raw !== "string" || !isAllowedTextLinkUrl(raw)) return "";
  try {
    return new URL(raw).toString();
  } catch {
    return "";
  }
};

import { useCallback, useEffect, useRef, useState } from "react";
import {
  T,
  TLBaseShape,
  TLShape,
  TldrawUiButton,
  TldrawUiButtonLabel,
  TldrawUiDialogBody,
  TldrawUiDialogCloseButton,
  TldrawUiDialogFooter,
  TldrawUiDialogHeader,
  TldrawUiDialogTitle,
  TldrawUiInput,
  track,
  useEditor,
} from "tldraw";
import {
  getTextShapeLinkUrl,
  isAllowedTextLinkUrl,
} from "~/components/canvas/utils/textShapeLink";

type ShapeWithUrl = TLBaseShape<string, { url: string }>;

// Text shapes keep their link in `meta` so the stock props schema is untouched;
// every other shape type uses tldraw's own `props.url`.
const isTextShape = (shape: TLShape): boolean => shape.type === "text";

const linkPatch = (shape: TLShape, url: string) =>
  isTextShape(shape) ? { meta: { url } } : { props: { url } };

const readLinkUrl = (shape: TLShape): string =>
  isTextShape(shape)
    ? getTextShapeLinkUrl(shape)
    : (((shape.props as { url?: unknown }).url as string | undefined) ?? "");

// Declared as a function property rather than reusing TLUiDialogProps, whose
// method-shorthand onClose trips @typescript-eslint/unbound-method.
type TextLinkDialogProps = { onClose: () => void };

type UrlValidity = { isValid: boolean; hasProtocol: boolean };

// Only text shapes carry the widened url validator. Geo and friends keep
// tldraw's T.linkUrl, so accepting obsidian:// for them would throw on save.
const validateUrlForShape = (url: string, shapeType: string): UrlValidity => {
  const isAllowed =
    shapeType === "text"
      ? (value: string) => isAllowedTextLinkUrl(value)
      : (value: string) => T.linkUrl.isValid(value);

  if (isAllowed(url)) return { isValid: true, hasProtocol: true };
  if (isAllowed(`https://${url}`)) return { isValid: true, hasProtocol: false };
  return { isValid: false, hasProtocol: false };
};

// A fork of tldraw's EditLinkDialog, which is not exported. Copy differs: the
// original's msg() keys are inlined, as this app has no i18n layer.
export const TextLinkDialog = track(({ onClose }: TextLinkDialogProps) => {
  const editor = useEditor();
  const selectedShape = editor.getOnlySelectedShape();

  const canEditLink =
    selectedShape &&
    (isTextShape(selectedShape) ||
      ("url" in selectedShape.props &&
        typeof selectedShape.props.url === "string"));

  if (!canEditLink) return null;

  return (
    <TextLinkDialogInner
      key={selectedShape.id}
      onClose={onClose}
      selectedShape={selectedShape as ShapeWithUrl}
    />
  );
});

const TextLinkDialogInner = track(
  ({
    onClose,
    selectedShape,
  }: TextLinkDialogProps & { selectedShape: ShapeWithUrl }) => {
    const editor = useEditor();
    const rInput = useRef<HTMLInputElement | null>(null);
    const shapeType = selectedShape.type;

    useEffect(() => {
      editor.timers.requestAnimationFrame(() => rInput.current?.focus());
    }, [editor]);

    const rInitialValue = useRef(readLinkUrl(selectedShape));

    const [urlInputState, setUrlInputState] = useState(() => {
      const initialUrl = readLinkUrl(selectedShape);
      const result = validateUrlForShape(initialUrl, shapeType);
      const initialValue = result.isValid
        ? result.hasProtocol
          ? initialUrl
          : `https://${initialUrl}`
        : "https://";
      return { actual: initialValue, safe: initialValue, valid: true };
    });

    const handleChange = useCallback(
      (rawValue: string) => {
        // Auto-correct a doubled https:// from a bad paste.
        const fixedRawValue = rawValue.replace(
          /https?:\/\/(https?:\/\/)/,
          (_match, arg1: string) => arg1,
        );
        const result = validateUrlForShape(fixedRawValue, shapeType);
        const safeValue = result.isValid
          ? result.hasProtocol
            ? fixedRawValue
            : `https://${fixedRawValue}`
          : "https://";

        setUrlInputState({
          actual: fixedRawValue,
          safe: safeValue,
          valid: result.isValid,
        });
      },
      [shapeType],
    );

    const handleClear = useCallback(() => {
      const onlySelectedShape = editor.getOnlySelectedShape();
      if (!onlySelectedShape) return;
      editor.updateShapes([
        {
          id: onlySelectedShape.id,
          type: onlySelectedShape.type,
          ...linkPatch(onlySelectedShape, ""),
        },
      ]);
      onClose();
    }, [editor, onClose]);

    const handleComplete = useCallback(() => {
      // Enter reaches this even while Save is disabled, and the fallback
      // "https://" fails both validators.
      if (!urlInputState.valid) return;
      const onlySelectedShape = editor.getOnlySelectedShape();
      if (!onlySelectedShape) return;
      if (readLinkUrl(onlySelectedShape) !== urlInputState.safe) {
        editor.updateShapes([
          {
            id: onlySelectedShape.id,
            type: onlySelectedShape.type,
            ...linkPatch(onlySelectedShape, urlInputState.safe),
          },
        ]);
      }
      onClose();
    }, [editor, onClose, urlInputState]);

    const handleCancel = useCallback(() => {
      onClose();
    }, [onClose]);

    const isRemoving = rInitialValue.current && !urlInputState.valid;

    return (
      <>
        <TldrawUiDialogHeader>
          <TldrawUiDialogTitle>Edit link</TldrawUiDialogTitle>
          <TldrawUiDialogCloseButton />
        </TldrawUiDialogHeader>
        <TldrawUiDialogBody>
          <div className="tlui-edit-link-dialog">
            <TldrawUiInput
              ref={rInput}
              className="tlui-edit-link-dialog__input"
              label="edit-link-dialog.url"
              autoFocus
              autoSelect
              placeholder="https://example.com"
              value={urlInputState.actual}
              onValueChange={handleChange}
              onComplete={handleComplete}
              onCancel={handleCancel}
            />
            <div>
              {!urlInputState.valid
                ? "Invalid URL"
                : shapeType === "text"
                  ? "Enter a URL, or an obsidian:// link to a page."
                  : "Enter a URL."}
            </div>
          </div>
        </TldrawUiDialogBody>
        <TldrawUiDialogFooter className="tlui-dialog__footer__actions">
          <TldrawUiButton
            type="normal"
            onClick={handleCancel}
            onTouchEnd={handleCancel}
          >
            <TldrawUiButtonLabel>Cancel</TldrawUiButtonLabel>
          </TldrawUiButton>
          {isRemoving ? (
            <TldrawUiButton
              type="danger"
              onClick={handleClear}
              onTouchEnd={handleClear}
            >
              <TldrawUiButtonLabel>Clear</TldrawUiButtonLabel>
            </TldrawUiButton>
          ) : (
            <TldrawUiButton
              type="primary"
              disabled={!urlInputState.valid}
              onClick={handleComplete}
              onTouchEnd={handleComplete}
            >
              <TldrawUiButtonLabel>Save</TldrawUiButtonLabel>
            </TldrawUiButton>
          )}
        </TldrawUiDialogFooter>
      </>
    );
  },
);

