1	// ENG-2228 text-shape links: meta.url storage + canvas overlay affordance.
2	// Harness contract: evaluate() bodies must start with an explicit `return`,
3	// waitFor() only succeeds on a literal true, key() takes an options object.
4	const CANVAS_CMD = "create-discourse-graph-canvas";
5	const ICON = ".tl-hyperlink-button";
6	
7	const VIEW = `app.workspace.getLeavesOfType("tldraw-dg-preview")[0].view`;
8	const TEXT_SHAPES = `${VIEW}.store.allRecords().filter((r) => r.typeName === "shape" && r.type === "text")`;
9	
10	const openCanvas = async ({ client, json, vault }) => {
11	  await client.evaluate(
12	    `return app.commands.executeCommandById(${json(`${vault.pluginId}:${CANVAS_CMD}`)});`,
13	  );
14	  await client.waitFor(`return !!document.querySelector(".tl-canvas");`, {
15	    label: "canvas mounted",
16	    timeout: 15000,
17	  });
18	  return client.evaluate(`return ${VIEW}.file.path;`);
19	};
20	
21	const canvasPoint = ({ client }, dx = 0, dy = 0) =>
22	  client.evaluate(`const r = document.querySelector(".tl-canvas").getBoundingClientRect();
23	    return { x: Math.round(r.left + r.width / 2 + ${dx}), y: Math.round(r.top + r.height / 2 + ${dy}) };`);
24	
25	const clickAt = async ({ client }, { x, y }, modifiers = 0, button = "left") => {
26	  for (const type of ["mousePressed", "mouseReleased"]) {
27	    await client.send("Input.dispatchMouseEvent", {
28	      type, x, y, button, clickCount: 1, modifiers,
29	      buttons: type === "mousePressed" ? (button === "right" ? 2 : 1) : 0,
30	    });
31	  }
32	};
33	
34	// A text shape made the way a user makes one: text tool, click, type, Escape.
35	const createTextShapeViaToolbar = async (ctx, text) => {
36	  const { client } = ctx;
37	  const point = await canvasPoint(ctx);
38	  await clickAt(ctx, point);
39	  await client.key({ text: "t", key: "t", code: "KeyT", windowsVirtualKeyCode: 84, nativeVirtualKeyCode: 84 });
