// ENG-2228: page links via patched tldraw (validator + HyperlinkButton + navigate-link listener).
// Harness contract: evaluate() bodies need an explicit `return`, waitFor() needs literal true,
// key() takes an options object. Every query is scoped to this run's own canvas leaf, because
// other sessions leave hidden canvas tabs open.
const CANVAS_CMD = "create-discourse-graph-canvas";
const LEAF = `window.__dgVerifyLeaf`;
const VIEW = `${LEAF}.view`;
const ROOT = `${VIEW}.containerEl`;
const TEXT_ICON = ".dg-text-link-anchor .tl-hyperlink-button";
const shapeIcon = (type) => `.tl-shape[data-shape-type='${type}'] .tl-hyperlink-button`;
const TEXT_SHAPES = `${VIEW}.store.allRecords().filter((r) => r.typeName === "shape" && r.type === "text")`;
// The editor is not exposed on the view; walk the React fiber up from .tl-canvas.
const EDITOR = `(() => { const el = ${ROOT}.querySelector(".tl-canvas");
  let f = el[Object.keys(el).find((k) => k.startsWith("__reactFiber$"))];
  while (f && !(f.memoizedProps && f.memoizedProps.value && f.memoizedProps.value.putExternalContent)) f = f.return;
  return f.memoizedProps.value; })()`;
const OPENED = (path) => `let hit = false;
  app.workspace.iterateAllLeaves((l) => { if (l !== ${LEAF} && l.view && l.view.file && l.view.file.path === ${JSON.stringify(path)}) hit = true; });
  return hit;`;

const openCanvas = async ({ client, json, vault }) => {
  await client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);
  await client.evaluate(
    `return app.commands.executeCommandById(${json(`${vault.pluginId}:${CANVAS_CMD}`)});`,
  );
  await client.waitFor(
    `const l = app.workspace.activeLeaf; return !!(l && l.view && l.view.getViewType && l.view.getViewType() === "tldraw-dg-preview" && l.view.containerEl.querySelector(".tl-canvas"));`,
    { label: "canvas mounted", timeout: 15000 },
  );
  await client.evaluate(`window.__dgVerifyLeaf = app.workspace.activeLeaf; return true;`);
  return client.evaluate(`return ${VIEW}.file.path;`);
};

const canvasPoint = ({ client }, dx = 0, dy = 0) =>
  client.evaluate(`const r = ${ROOT}.querySelector(".tl-canvas").getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2 + ${dx}), y: Math.round(r.top + r.height / 2 + ${dy}) };`);

const clickAt = async ({ client }, { x, y }, modifiers = 0, button = "left") => {
  for (const type of ["mousePressed", "mouseReleased"]) {
    await client.send("Input.dispatchMouseEvent", {
      type, x, y, button, clickCount: 1, modifiers,
      buttons: type === "mousePressed" ? (button === "right" ? 2 : 1) : 0,
    });
  }
};

// A text shape made the way a user makes one: text tool, click, type, Escape.
const createTextShapeViaToolbar = async (ctx, text) => {
  const { client } = ctx;
  const point = await canvasPoint(ctx);
  await clickAt(ctx, point);
  await client.key({ text: "t", key: "t", code: "KeyT", windowsVirtualKeyCode: 84, nativeVirtualKeyCode: 84 });
  await clickAt(ctx, point);
  await client.waitFor(`return !!${ROOT}.querySelector(".tl-text-input, [contenteditable=true]");`, {
    label: "text editor open", timeout: 5000,
  });
  await client.typeText(text);
  await client.pressEscape();
  await client.waitFor(`return ${TEXT_SHAPES}.length > 0;`, { label: "text shape in store", timeout: 10000 });
  return client.evaluate(`const t = ${TEXT_SHAPES}; const s = t[t.length - 1];
    return { id: s.id, metaKeys: Object.keys(s.meta), propKeys: Object.keys(s.props).sort() };`);
};

const setTextLink = ({ client, json }, shapeId, url) =>
  client.evaluate(`const v = ${VIEW}; const s = v.store.get(${json(shapeId)});
    v.store.put([{ ...s, meta: { ...s.meta, url: ${json(url)} } }]);
    return true;`);

const pageLinkFor = async ({ client, json }) => {
  const path = await client.evaluate(`return app.vault.getMarkdownFiles()
    .find((f) => !f.path.startsWith("_verify/") && !f.path.startsWith("Discourse Canvas/"))?.path ?? null;`);
  const url = await client.evaluate(`return "obsidian://open?vault=" + encodeURIComponent(app.vault.getName())
    + "&file=" + encodeURIComponent(${json(path)});`);
  return { path, url };
};

// Creates a shape through the editor so tldraw fills every default prop; returns the error text if rejected.
const createLinkedShape = ({ client, json }, type, url, extraProps = {}) =>
  client.evaluate(`try {
      const editor = ${EDITOR};
      const c = editor.getViewportPageBounds().center;
      editor.createShape({ type: ${json(type)}, x: c.x - 100, y: c.y - 60,
        props: { ...${json(extraProps)}, url: ${json(url)} } });
      return "accepted";
    } catch (e) { return "REJECTED: " + (e.message || e); }`);

const clickShapeIconAndWait = async ({ client, json }, selector, path) => {
  await client.waitFor(`return !!${ROOT}.querySelector(${json(selector)});`, { label: "link icon", timeout: 8000 });
  const hrefOmitted = await client.evaluate(`return !${ROOT}.querySelector(${json(selector)}).hasAttribute("href");`);
  await client.evaluate(`${ROOT}.querySelector(${json(selector)}).click(); return true;`);
  const opened = await client
    .waitFor(OPENED(path), { label: "page opened in app", timeout: 8000 })
    .then(() => true)
    .catch(() => false);
  return { hrefOmitted, opened };
};

export default [
  {
    name: "Toolbar text shape is untouched stock",
    input: "text tool, click canvas, type 'linked note', Escape",
    expected: "no url in props, empty meta: stock text schema",
    run: async (ctx) => {
      await openCanvas(ctx);
      return createTextShapeViaToolbar(ctx, "linked note");
    },
    expect: (a) => ({
      pass: !!a && !a.propKeys.includes("url") && a.metaKeys.length === 0,
      actual: `props=[${a?.propKeys}] meta=[${a?.metaKeys}]`,
    }),
  },
  {
    name: "Edit link appears for a text shape",
    input: "select the text shape, right-click, open the Edit submenu",
    expected: "Edit link listed for a shape with no link yet",
    run: async (ctx) => {
      const { client } = ctx;
      await openCanvas(ctx);
      await createTextShapeViaToolbar(ctx, "linked note");
      const pos = await client.evaluate(`const el = ${ROOT}.querySelector('.tl-shape[data-shape-type="text"]');
        const r = el.getBoundingClientRect();
        return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };`);
      await clickAt(ctx, pos);
      await clickAt(ctx, pos, 0, "right");
      await client.waitFor(`return !!document.querySelector('[role="menuitem"]');`, { label: "context menu" });
      await client.evaluate(`const t = [...document.querySelectorAll('[role="menuitem"]')]
          .find((e) => e.textContent.trim() === "Edit");
        if (t) t.click();
        return !!t;`);
      await new Promise((r) => setTimeout(r, 500));
      return client.evaluate(`return [...document.querySelectorAll('[role="menuitem"], button')]
        .some((e) => e.textContent.trim().toLowerCase() === "edit link");`);
    },
    expect: (a) => ({ pass: a === true, actual: a ? "Edit link present" : "Edit link MISSING" }),
  },
  {
    name: "Text link renders tldraw's own button beside the text",
    input: "set meta.url on a text shape",
    expected: "one stock hyperlink button, clear of the text, vertically centred",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      await setTextLink(ctx, shape.id, "https://example.com");
      await client.waitFor(`return ${ROOT}.querySelectorAll(${json(TEXT_ICON)}).length > 0;`, {
        label: "icon rendered", timeout: 10000,
      });
      return client.evaluate(`const b = ${ROOT}.querySelector(${json(TEXT_ICON)}).getBoundingClientRect();
        const s = ${ROOT}.querySelector('.tl-shape[data-shape-type="text"]').getBoundingClientRect();
        return { count: ${ROOT}.querySelectorAll(${json(TEXT_ICON)}).length,
          clearOfText: b.left >= s.right - 1,
          centred: Math.abs((b.top + b.bottom) / 2 - (s.top + s.bottom) / 2) <= 3 };`);
    },
    expect: (a) => ({
      pass: a.count === 1 && a.clearOfText && a.centred,
      actual: `${a.count} button(s), clearOfText=${a.clearOfText}, centred=${a.centred}`,
    }),
  },
  {
    name: "Text link: click opens the page, Cmd+click opens a new tab",
    input: "obsidian:// link on a text shape; click the button, then Cmd+click it",
    expected: "no href; page opens in the sidebar, then Cmd+click adds a root tab",
    run: async (ctx) => {
      const { client, json } = ctx;
      await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      const { path, url } = await pageLinkFor(ctx);
      await setTextLink(ctx, shape.id, url);
      const { hrefOmitted, opened } = await clickShapeIconAndWait(ctx, TEXT_ICON, path);
      const count = `let n = 0; app.workspace.iterateRootLeaves(() => { n++; }); return n;`;
      const before = await client.evaluate(count);
      await client.evaluate(`${ROOT}.querySelector(${json(TEXT_ICON)})
          .dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, metaKey: true }));
        return true;`);
      await new Promise((r) => setTimeout(r, 800));
      const after = await client.evaluate(count);
      return { path, hrefOmitted, opened, before, after };
    },
    expect: (a) => ({
      pass: a.hrefOmitted && a.opened && a.after > a.before,
      actual: `href omitted=${a.hrefOmitted}, plain click opened=${a.opened}, root tabs ${a.before}→${a.after} on Cmd+click`,
    }),
  },
  {
    name: "Text link persists across close and reopen",
    input: "set a link, let autosave run, close and reopen the canvas",
    expected: "markdown holds meta.url, props has no url, button returns",
    run: async (ctx) => {
      const { client, json } = ctx;
      const path = await openCanvas(ctx);
      const shape = await createTextShapeViaToolbar(ctx, "linked note");
      await setTextLink(ctx, shape.id, "https://persist.example.com");
      // tldraw flushes its reactor on real input, which is what triggers the autosave
      await clickAt(ctx, await canvasPoint(ctx, -200, -150));
      await client.waitFor(
        `return app.vault.adapter.read(${json(path)}).then((t) => t.includes("persist.example.com"));`,
        { label: "link written to markdown", timeout: 20000 },
      );
      const facts = await client.evaluate(`return app.vault.adapter.read(${json(path)}).then((t) => {
        const d = JSON.parse(t.match(/\\{[\\s\\S]*\\}/)[0]);
        const text = Object.values(d.raw.records).filter((r) => r.type === "text");
        return { metaUrls: text.map((r) => (r.meta && r.meta.url) || null),
          propUrls: text.map((r) => r.props.url || null) };
      });`);
      await client.evaluate(`${LEAF}.detach(); return true;`);
      await client.evaluate(`return app.workspace.getLeaf("tab")
        .openFile(app.vault.getAbstractFileByPath(${json(path)}));`);
      await client.waitFor(
        `const l = app.workspace.activeLeaf; return !!(l && l.view && l.view.file && l.view.file.path === ${json(path)} && l.view.containerEl.querySelector(".tl-canvas"));`,
        { label: "canvas reopened", timeout: 15000 },
      );
      await client.evaluate(`window.__dgVerifyLeaf = app.workspace.activeLeaf; return true;`);
      await client.waitFor(`return ${ROOT}.querySelectorAll(${json(TEXT_ICON)}).length > 0;`, {
        label: "button after reopen", timeout: 10000,
      });
      const back = await client.evaluate(`return ${ROOT}.querySelectorAll(${json(TEXT_ICON)}).length;`);
      return { ...facts, back };
    },
    expect: (a) => ({
      pass: a.metaUrls.includes("https://persist.example.com") && a.propUrls.every((u) => u === null) && a.back >= 1,
      actual: `meta=${JSON.stringify(a.metaUrls)} props=${JSON.stringify(a.propUrls)} buttonsAfterReopen=${a.back}`,
    }),
  },
  {
    name: "Geo shape accepts and opens a page link",
    input: "rectangle with an obsidian://open link; click its stock button",
    expected: "schema accepts it, no href, page opens in the app",
    run: async (ctx) => {
      await openCanvas(ctx);
      const { path, url } = await pageLinkFor(ctx);
      const accepted = await createLinkedShape(ctx, "geo", url, { w: 220, h: 120 });
      if (accepted !== "accepted") return { accepted };
      return { accepted, ...(await clickShapeIconAndWait(ctx, shapeIcon("geo"), path)) };
    },
    expect: (a) => ({
      pass: a.accepted === "accepted" && a.hrefOmitted === true && a.opened === true,
      actual: `schema=${a.accepted}, href omitted=${a.hrefOmitted}, opened=${a.opened}`,
    }),
  },
  {
    name: "Geo link stored as Obsidian:// (mixed case) still opens",
    input: "rectangle with Obsidian://open?… (the validator accepts it); click the button",
    expected: "page opens in the app, no 'not in this vault' toast",
    run: async (ctx) => {
      await openCanvas(ctx);
      const { path, url } = await pageLinkFor(ctx);
      const mixed = url.replace(/^obsidian:/, "Obsidian:");
      const accepted = await createLinkedShape(ctx, "geo", mixed, { w: 220, h: 120 });
      if (accepted !== "accepted") return { accepted };
      return { accepted, ...(await clickShapeIconAndWait(ctx, shapeIcon("geo"), path)) };
    },
    expect: (a) => ({
      pass: a.accepted === "accepted" && a.opened === true,
      actual: `schema=${a.accepted}, opened=${a.opened}`,
    }),
  },
  {
    name: "Note shape accepts and opens a page link",
    input: "sticky note with an obsidian://open link; click its stock button",
    expected: "schema accepts it, no href, page opens in the app",
    run: async (ctx) => {
      await openCanvas(ctx);
      const { path, url } = await pageLinkFor(ctx);
      const accepted = await createLinkedShape(ctx, "note", url);
      if (accepted !== "accepted") return { accepted };
      return { accepted, ...(await clickShapeIconAndWait(ctx, shapeIcon("note"), path)) };
    },
    expect: (a) => ({
      pass: a.accepted === "accepted" && a.hrefOmitted === true && a.opened === true,
      actual: `schema=${a.accepted}, href omitted=${a.hrefOmitted}, opened=${a.opened}`,
    }),
  },
  {
    name: "Validator still rejects obsidian action URIs",
    input: "rectangle with obsidian://advanced-uri?commandid=…, and with obsidian://open without file",
    expected: "both rejected by the patched validator",
    run: async (ctx) => {
      await openCanvas(ctx);
      const action = await createLinkedShape(ctx, "geo", "obsidian://advanced-uri?vault=v&commandid=app%3Areload", { w: 220, h: 120 });
      const noFile = await createLinkedShape(ctx, "geo", "obsidian://open?vault=v", { w: 220, h: 120 });
      return { action, noFile };
    },
    expect: (a) => ({
      pass: a.action.startsWith("REJECTED") && a.noFile.startsWith("REJECTED"),
      actual: `advanced-uri: ${a.action.slice(0, 60)} | open without file: ${a.noFile.slice(0, 60)}`,
    }),
  },
];

